// Azura World CATI — frozen interfaces.
//
// This file is the EXECUTABLE FORM of `CONTRACTS.md`. The document is the
// specification; this file is the implementation. They must not drift.
//
// Owned by W0-A. Every parallel window compiles against this file. It does not
// change during a wave: if a contract here is wrong, stop, report, amend
// `CONTRACTS.md` centrally, bump CONTRACT_VERSION, restart affected tasks
// (ORCHESTRATION §7). Do not edit this file to make your own code compile.
//
// Dependency-free on purpose — no imports, no Node built-ins, no filesystem.
// It is therefore safe in both the server and the client bundle, and it can be
// loaded by `node --experimental-strip-types` (which means: no `enum`, no
// `namespace`, and no constructor parameter properties in this file, ever).

/** Version of the frozen contract surface. Bumped only by a central amendment. */
export const CONTRACT_VERSION = 1 as const

// ---------------------------------------------------------------------------
// 1. Provenance
// ---------------------------------------------------------------------------

/** How well established a fact is. `"gap"` MUST carry `value === null`. */
export type Confidence =
  | "confirmed" // ≥2 independent sources agree
  | "official" // stated by azuraworld.com or a Cebeci Group domain
  | "single_source" // one source only, uncontradicted
  | "conflicted" // sources disagree; see conflictsWith
  | "inferred" // derived by computation from confirmed facts; note explains how
  | "gap" // not established — value MUST be null

/** Resolution order when sources disagree. Lower number wins the DISPLAY value. */
export type SourceTier =
  | 1 // official        — azuraworld.com
  | 2 // developer       — cebecigroup.com, alanyacebeci.com
  | 3 // hotel operation — azuraworldhotel.com
  | 4 // portal          — terra, alanya-home, housearch, haspo, seaside, realtygroup, ivm
  | 5 // review/booking  — tripadvisor, booking, agoda, onthebeach
  | 6 // press/secondary — enspride, turizmguncel, kalinka, cestate

/** One citation: where a value came from and the snapshot that proves it. */
export interface SourceRef {
  url: string
  /** Publisher label for UI, e.g. "Seaside Alanya" */
  publisher: string
  /** ISO 8601. When the harvester actually retrieved this. */
  fetchedAt: string
  /** sha256 of the stored raw snapshot under sources/raw/ */
  snapshotHash: string
  tier: SourceTier
}

/** A value that cannot be displayed without the sources that produced it. */
export interface SourcedFact<T> {
  value: T | null
  sources: SourceRef[]
  confidence: Confidence
  /** Populated iff confidence === "conflicted". Never empty when it is. */
  conflictsWith?: Array<{ value: unknown; source: SourceRef }>
  /** Required for "inferred" and "gap". Explains the derivation or the absence. */
  note?: string
}

// ---------------------------------------------------------------------------
// 2. Dataset
// ---------------------------------------------------------------------------

// CONTRACT-GAP-01 / CONTRACT-GAP-02 — grep these ids.
//
// `AzuraWorldDataset.blocks` is typed `AzuraBlock[]` and `.amenities` is typed
// `Amenity[]` in CONTRACTS.md §2, but NEITHER interface is defined anywhere in
// that document. They are declared here as open records rather than invented
// shapes: this file transcribes the specification, it does not extend it.
//
// Consequence for downstream windows: you can carry these values around, but
// you cannot read a named property off one without a cast, and you must not add
// one here. Before any window relies on specific fields, CONTRACTS.md must be
// amended centrally and CONTRACT_VERSION bumped (ORCHESTRATION §8). Reported in
// HANDOFF/W0-A.md.

/** CONTRACT-GAP-01 — referenced by CONTRACTS.md §2 but never defined there. */
export type AzuraBlock = Record<string, unknown>

/** CONTRACT-GAP-02 — referenced by CONTRACTS.md §2 but never defined there. */
export type Amenity = Record<string, unknown>

/** The whole generated dataset. Generated file — never hand-edit; fix the parser. */
export interface AzuraWorldDataset {
  generatedAt: string
  contractVersion: 1
  harvest: HarvestEntry[]
  project: AzuraProject
  blocks: AzuraBlock[]
  units: AzuraUnit[]
  hotel: AzuraHotel
  reviews: ReviewSource[]
  portalListings: PortalListing[]
  amenities: Amenity[]
  findings: Finding[]
}

/** One harvester attempt against one URL, successful or not. */
export interface HarvestEntry {
  url: string
  publisher: string
  tier: SourceTier
  /** HTTP status, or a transport error label: "dns_timeout" | "tls_invalid" | "blocked_403" */
  status: number | string
  fetchedAt: string
  snapshotPath: string | null
  snapshotHash: string | null
  bytes: number
  /** false when the body was a soft-404 or bot wall wearing a 200 */
  contentValidated: boolean
}

