  plotAreaSqm: SourcedFact<number>
  greenAreaSqm: SourcedFact<number>
  buildingFootprintSqm: SourcedFact<number>
  outdoorFacilityAreaSqm: SourcedFact<number>
  residenceBlockCount: SourcedFact<number>
  buildingCount: SourcedFact<number>
  floorsPerBuilding: SourcedFact<number>
  totalUnits: SourcedFact<number>
  constructionStart: SourcedFact<string> // ISO date
  completionDate: SourcedFact<string> // ISO date
  buildStatus: SourcedFact<"planned" | "under_construction" | "completed">
  distanceToSeaM: SourcedFact<number>
  distanceToAlanyaCentreKm: SourcedFact<number>
  distanceToGazipasaAirportKm: SourcedFact<number>
  distanceToAntalyaAirportKm: SourcedFact<number>
  downPaymentPercent: SourcedFact<number>
