// ---------------------------------------------------------------------------
// 4. Repository envelope
// ---------------------------------------------------------------------------

/**
 * Every repository function returns this. Never throw for "Supabase not
 * configured" — fall back to the local seed and label it. Do throw when a
 * *configured* Supabase returns a real error; a silent fallback hides an outage.
 */
export interface RepositoryResult<T> {
  data: T
  source: "supabase" | "local-seed"
  /** Present when source === "local-seed" AND Supabase was expected. Explains the fallback. */
  degradedReason?: string
  fetchedAt: string
}

// ---------------------------------------------------------------------------
// 5. API envelope
// ---------------------------------------------------------------------------

/** Discriminated API envelope. Check `ok` before touching `data` or `error`. */
export type ApiResponse<T> =
  | { ok: true; data: T; source: "supabase" | "local-seed"; requestId: string }
  | { ok: false; error: ApiError; requestId: string }

/** A handled failure. Never 500 for one of these — a 500 means we have a bug. */
export interface ApiError {
  code:
    | "unauthorized"
    | "forbidden"
    | "not_found"
    | "validation_failed"
    | "rate_limited"
    | "conflict"
    | "persistence_unavailable"
    | "upstream_failed"
  message: string // safe for display; never contains internals
  details?: Record<string, string>
  retryable: boolean
}

/** Fixed code → HTTP status mapping from CONTRACTS.md §5. Frozen; tested by W4-D. */
export const apiErrorStatus: Record<ApiError["code"], number> = Object.freeze({
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  persistence_unavailable: 503,
  upstream_failed: 502,
})

