// ---------------------------------------------------------------------------
// Runtime guards
// ---------------------------------------------------------------------------

/** Options for `assertFactInvariants`. */
export interface AssertFactOptions {
  /** Invariant 6. When supplied, every source's snapshotHash is checked against it.
   *  W0-B's verify-evidence.mjs and W4-D's contract suite supply a real fs-backed resolver. */
  snapshotExists?: (snapshotHash: string) => boolean
}

/**
 * Thrown by `assertFactInvariants`. Carries the dotted `path` of the offending
 * fact and the number (1–6) of the CONTRACTS.md §1 invariant that fired, so a
 * test can assert *which* rule broke rather than only that something threw.
 */
export class FactInvariantError extends Error {
  /** Dotted path of the offending fact, e.g. "project.residenceBlockCount". */
  readonly path: string
  /** Which CONTRACTS.md §1 invariant fired (1–6). */
  readonly invariant: 1 | 2 | 3 | 4 | 5 | 6

  constructor(invariant: 1 | 2 | 3 | 4 | 5 | 6, path: string, reason: string) {
    super(`SourcedFact invariant ${invariant} violated at ${path}: ${reason}`)
    this.name = "FactInvariantError"
    this.path = path
    this.invariant = invariant
  }
}

/** sha256, lower-case hex. The shape every `SourceRef.snapshotHash` must have. */
const SNAPSHOT_HASH_PATTERN = /^[0-9a-f]{64}$/

const CONFIDENCE_VALUES = [
  "confirmed",
  "official",
  "single_source",
  "conflicted",
  "inferred",
  "gap",
] as const

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function isUnknownArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value)
}

function isConfidence(value: unknown): value is Confidence {
  if (typeof value !== "string") return false
  return CONFIDENCE_VALUES.some((candidate) => candidate === value)
}

function isSourceTier(value: unknown): value is SourceTier {
  return (
    value === 1 ||
    value === 2 ||
    value === 3 ||
    value === 4 ||
    value === 5 ||
    value === 6
  )
}

function isSourceRef(value: unknown): value is SourceRef {
  if (!isRecord(value)) return false
  return (
    typeof value["url"] === "string" &&
    typeof value["publisher"] === "string" &&
    typeof value["fetchedAt"] === "string" &&
    typeof value["snapshotHash"] === "string" &&
    isSourceTier(value["tier"])
  )
}

/**
 * Lower-cased hostname of a source URL, for invariant 3's "distinct hosts" test.
 * A URL that does not parse is itself a violation — a citation you cannot
 * re-open is not a citation — and is reported under invariant 3, the only
 * invariant that needs hostnames.
 */
function hostname(source: SourceRef, path: string): string {
  try {
    return new URL(source.url).hostname.toLowerCase()
  } catch {
    throw new FactInvariantError(
      3,
      path,
      `source url is not a parseable URL: ${JSON.stringify(source.url)}`
    )
  }
}

/**
 * Structural check that `v` is a `SourcedFact`. The generic `T` is not and
 * cannot be checked at runtime — this narrows the envelope, not the value.
 */
export function isSourcedFact<T>(v: unknown): v is SourcedFact<T> {
  if (!isRecord(v)) return false
  if (!("value" in v)) return false
  if (!isConfidence(v["confidence"])) return false

  const sources = v["sources"]
  if (!isUnknownArray(sources)) return false
  if (!sources.every(isSourceRef)) return false

  const conflictsWith = v["conflictsWith"]
  if (conflictsWith !== undefined && !isUnknownArray(conflictsWith)) return false

  const note = v["note"]
  if (note !== undefined && typeof note !== "string") return false

  return true
}

/**
 * Enforces all six `SourcedFact` invariants from CONTRACTS.md §1 and throws a
 * `FactInvariantError` naming the dotted `path` and the invariant number.
 *
 * Invariant 6 ("every snapshotHash resolves to a real file under sources/raw/")
 * cannot be checked from a browser-safe, filesystem-free module. It is split:
 * the *shape* of every snapshotHash (64 lower-case hex chars) is always
 * enforced, so a malformed hash is caught everywhere; *existence* is enforced
 * only when `options.snapshotExists` is supplied. Callers with filesystem
 * access — W0-B's verify-evidence.mjs and W4-D's contract suite — must supply
 * it, or invariant 6 is only half-enforced.
 */
export function assertFactInvariants<T>(
  f: SourcedFact<T>,
  path: string,
  options?: AssertFactOptions
): void {
  const note = typeof f.note === "string" ? f.note.trim() : ""

  // 1. gap ⟹ value === null and note is non-empty.
  if (f.confidence === "gap") {
    if (f.value !== null) {
      throw new FactInvariantError(
        1,
        path,
        'confidence is "gap" but value is not null'
      )
    }
    if (note.length === 0) {
      throw new FactInvariantError(
        1,
        path,
        'confidence is "gap" but note is missing or blank'
      )
    }
  }

  // 2. conflicted ⟹ conflictsWith.length >= 1.
  if (f.confidence === "conflicted") {
    const conflicts = f.conflictsWith
    if (conflicts === undefined || conflicts.length < 1) {
      throw new FactInvariantError(
        2,
        path,
        'confidence is "conflicted" but conflictsWith is empty or absent'
      )
    }
  }

  // 3. confirmed ⟹ sources.length >= 2 with distinct hosts.
  // Hosts are extracted for every fact so an unparseable citation URL is caught
  // regardless of confidence; the >= 2 rule applies only to "confirmed".
  const hosts = new Set<string>()
  for (const source of f.sources) {
    hosts.add(hostname(source, path))
  }
  if (f.confidence === "confirmed") {
    if (f.sources.length < 2) {
      throw new FactInvariantError(
        3,
        path,
        `confidence is "confirmed" but there are only ${f.sources.length} source(s)`
      )
    }
    if (hosts.size < 2) {
      throw new FactInvariantError(
        3,
        path,
        `confidence is "confirmed" but all ${f.sources.length} sources share the host "${
          Array.from(hosts)[0] ?? ""
        }"`
      )
    }
  }

  // 4. inferred ⟹ note explains the computation.
  if (f.confidence === "inferred" && note.length === 0) {
    throw new FactInvariantError(
      4,
      path,
      'confidence is "inferred" but note is missing or blank'
    )
  }

  // 5. sources.length === 0 is only legal when confidence === "gap".
  if (f.sources.length === 0 && f.confidence !== "gap") {
    throw new FactInvariantError(
      5,
      path,
      `sources is empty but confidence is "${f.confidence}"`
    )
  }

  // 6. Every snapshotHash resolves to a real file under sources/raw/.
  const snapshotExists = options?.snapshotExists
  for (const source of f.sources) {
    const hash = source.snapshotHash
    if (!SNAPSHOT_HASH_PATTERN.test(hash)) {
      throw new FactInvariantError(
        6,
        path,
        `snapshotHash ${JSON.stringify(hash)} for ${source.url} is not 64 lower-case hex characters`
      )
    }
    if (snapshotExists !== undefined && !snapshotExists(hash)) {
      throw new FactInvariantError(
        6,
        path,
        `snapshotHash ${hash} for ${source.url} does not resolve to a file under sources/raw/`
      )
    }
  }
}

/**
 * The value safe to render. Returns `null` for a `"gap"` regardless of what is
 * stored, so a gap can never leak a stale value into the UI.
 */
export function displayValue<T>(f: SourcedFact<T>): T | null {
  if (f.confidence === "gap") return null
  return f.value
}

/**
 * Picks the source that wins the DISPLAY value: the lower `tier` number wins.
 *
 * Tie-break, chosen so the function is total and deterministic:
 *   1. equal tier → the more recent `fetchedAt` wins;
 *   2. equal or unparseable `fetchedAt` → `a` wins, so the result is stable and
 *      the function is a valid reducer regardless of argument order noise.
 * The losing source is never discarded — CONTRACTS.md §8 requires it stay
 * stored and visible on demand.
 */
export function tierWins(a: SourceRef, b: SourceRef): SourceRef {
  if (a.tier !== b.tier) return a.tier < b.tier ? a : b

  const aFetched = Date.parse(a.fetchedAt)
  const bFetched = Date.parse(b.fetchedAt)
  if (Number.isNaN(aFetched) || Number.isNaN(bFetched)) return a
  if (aFetched !== bFetched) return aFetched > bFetched ? a : b

  return a
}
